input.new_string:
// ---- bulk selection ----
window.toggleSelect=function(id){
  if(selected[id]) delete selected[id]; else selected[id]=true;
  render();
};
function selectedItems(){ return items.filter(function(b){return selected[b.id];}); }

function updateBulkUI(){
  var bar=document.getElementById('bulkbar');
  var saEl=document.getElementById('selectall');
  var n=selCount();
  // select-all reflects whether every currently shown item is selected
  saEl.checked = lastShown.length>0 && lastShown.every(function(b){return selected[b.id];});
  if(n===0){ bar.classList.remove('show'); return; }
  bar.classList.add('show');
  document.getElementById('bulkcount').textContent=n+' selected';
  var acts=document.getElementById('bulkactions');
  if(currentTab==='archived'){
    acts.innerHTML=
      '<button onclick="bulkRestore()">Restore</button>'+
      '<button class="danger" onclick="bulkDelete()">Delete permanently</button>';
  } else {
    acts.innerHTML=
      '<button onclick="bulkAddTags()">Add tags…</button>'+
      '<button onclick="bulkRemoveTags()">Remove tags…</button>'+
      '<button onclick="bulkMark(\'unread\')">Mark “To read”</button>'+
      '<button onclick="bulkMark(\'done\')">Mark finished</button>'+
      '<button onclick="bulkArchive()">Archive</button>'+
      '<button class="danger" onclick="bulkDelete()">Delete</button>';
  }
}

document.getElementById('selectall').addEventListener('change',function(){
  if(this.checked){ lastShown.forEach(function(b){selected[b.id]=true;}); }
  else { lastShown.forEach(function(b){delete selected[b.id];}); }
  render();
});
document.getElementById('bulkclear').addEventListener('click',function(){ selected={}; render(); });

function parseTagList(raw){return raw?raw.split(',').map(function(t){return t.trim();}).filter(Boolean):[];}
window.bulkAddTags=function(){
  var raw=window.prompt('Add these tags to '+selCount()+' bookmark(s) (comma separated):'); if(raw===null) return;
  var add=parseTagList(raw); if(!add.length) return;
  selectedItems().forEach(function(b){
    add.forEach(function(t){ if(!(b.tags||[]).some(function(x){return x.toLowerCase()===t.toLowerCase();})) b.tags.push(t); });
  });
  rememberTags(add); render();
};
window.bulkRemoveTags=function(){
  var raw=window.prompt('Remove these tags from '+selCount()+' bookmark(s) (comma separated):'); if(raw===null) return;
  var rem=parseTagList(raw).map(function(t){return t.toLowerCase();}); if(!rem.length) return;
  selectedItems().forEach(function(b){ b.tags=(b.tags||[]).filter(function(t){return rem.indexOf(t.toLowerCase())<0;}); });
  render();
};
window.bulkMark=function(status){ selectedItems().forEach(function(b){b.status=status;}); render(); };
window.bulkArchive=function(){ selectedItems().forEach(function(b){b.archived=true;}); selected={}; render(); };
window.bulkRestore=function(){ selectedItems().forEach(function(b){b.archived=false;}); selected={}; render(); };
window.bulkDelete=function(){
  var n=selCount();
  if(!window.confirm('Delete '+n+' bookmark(s) permanently? This cannot be undone.')) return;
  items=items.filter(function(b){return !selected[b.id];}); selected={}; render();
};

