function esc(s){return String(s).replace(/[&<>"']/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}

// simple, safe note formatting: **bold**, *italic*, [text](http-url), "- " bullets, line breaks
function renderNote(md){
  if(!md) return '';
  var lines=String(md).split(/\r?\n/), html='', inList=false;
  function inline(s){
    s=esc(s);
    s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,function(m,t,u){
      return '<a href="'+u+'" target="_blank" rel="noopener">'+t+'</a>';});
    s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    s=s.replace(/\*([^*]+)\*/g,'<em>$1</em>');
    return s;
  }
  lines.forEach(function(ln){
    var m=ln.match(/^\s*[-*]\s+(.*)$/);
    if(m){ if(!inList){html+='<ul>';inList=true;} html+='<li>'+inline(m[1])+'</li>'; }
    else { if(inList){html+='</ul>';inList=false;}
