var searchEl=document.getElementById('search'), clearEl=document.getElementById('clearsearch');
var saveSearchBtn=document.getElementById('savesearch');
function syncSearchButtons(){
  clearEl.classList.toggle('show',!!query);
  saveSearchBtn.disabled = !query.trim();
}
searchEl.addEventListener('input',function(){
  query=searchEl.value;
  syncSearchButtons();
  render();
});
clearEl.addEventListener('click',function(){
  query=''; searchEl.value=''; syncSearchButtons(); render(); searchEl.focus();
});

// ---- reusable saved searches ----
var savedSearches=[];
saveSearchBtn.addEventListener('click',function(){
  var q=query.trim(); if(!q) return;
  var name=window.prompt('Name this saved search:', q); if(name===null) return;
  name=name.trim()||q;
  savedSearches.push({id:Date.now(), name:name, query:q});
  renderSavedSearches();
});
function renderSavedSearches(){
  var wrap=document.getElementById('savedsearches');
  wrap.innerHTML=savedSearches.map(function(s){
    return '<span class="savedchip" onclick="runSaved('+s.id+')" title="'+esc(s.query)+'">'+
      '<span class="star">★</span>'+esc(s.name)+
      '<button class="x" title="Remove" onclick="event.stopPropagation();deleteSaved('+s.id+')">✕</button></span>';
  }).join('');
}
window.runSaved=function(id){
  var s=savedSearches.find(function(x){return x.id===id;}); if(!s) return;
  query=s.query; searchEl.value=s.query; syncSearchButtons(); render();
  window.scrollTo({top:0,behavior:'smooth'});
};
window.deleteSaved=function(id){
  savedSearches=savedSearches.filter(function(x){return x.id!==id;}); renderSavedSearches();
};
syncSearchButtons();

