var savedSearches=[];
saveSearchBtn.addEventListener('click',function(){
  var q=query.trim(); if(!q) return;
  var name=window.prompt('Name this saved search:', q); if(name===null) return;
  name=name.trim()||q;
  savedSearches.push({id:Date.now(), name:name, query:q});
  renderSavedSearches();
});
function renderSavedSearches(){
  var wrap=document.getElementById('savedsearches');
  wrap.innerHTML=savedSearches.map(function(s){
    return '<span class="savedchip" onclick="runSaved('+s.id+')" title="'+esc(s.query)+'">'+
      '<span class="star">★</span>'+esc(s.name)+
      '<button class="x" title="Remove" onclick="event.stopPropagation();deleteSaved('+s.id+')">✕</button></span>';
  }).join('');
}
window.runSaved=function(id){
  var s=savedSearches.find(function(x){return x.id===id;}); if(!s) return;
