// ---- import / export (Netscape bookmark HTML format) ----
function exportHTML(){
  var lines=['<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>','<H1>Bookmarks</H1>','<DL><p>'];
  items.forEach(function(b){
    var add=Math.floor((b.added||b.id)/1000);
    var attrs='HREF="'+esc(b.url)+'" ADD_DATE="'+add+'"';
    if(b.tags&&b.tags.length) attrs+=' TAGS="'+esc(b.tags.join(','))+'"';
    lines.push('    <DT><A '+attrs+'>'+esc(b.title||b.url)+'</A>');
    if(b.desc) lines.push('    <DD>'+esc(b.desc));
  });
  lines.push('</DL><p>');
  var blob=new Blob([lines.join('\n')],{type:'text/html'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download='bookmarks.html';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  document.getElementById('importmsg').textContent='Exported '+items.length+' bookmark(s).';
}
function importHTML(text){
  var doc=new DOMParser().parseFromString(text,'text/html');
  var anchors=doc.querySelectorAll('a[href]');
  var added=0, skipped=0;
  anchors.forEach(function(a){
    var url=a.getAttribute('href'); if(!url||!isValidUrl(url)){skipped++;return;}
    if(items.some(function(x){return normalize(x.url)===normalize(url);})){skipped++;return;}
    var addRaw=a.getAttribute('add_date');
    var addedTs=addRaw?parseInt(addRaw,10)*1000:Date.now();
    var tagsAttr=a.getAttribute('tags')||'';
    var tags=tagsAttr?tagsAttr.split(',').map(function(t){return t.trim();}).filter(Boolean):[];
    // description sometimes follows as a <dd>
    var desc=''; var dd=a.parentNode&&a.parentNode.nextElementSibling;
    if(dd&&dd.tagName==='DD') desc=dd.textContent.trim();
    var dom=domainOf(url);
    items.push({id:Date.now()+Math.random(), url:url, title:(a.textContent||url).trim(), desc:desc,
      note:'', tags:tags, dom:dom, img:previewImg(dom),
      status:'unread', archived:false, added:addedTs,
      snapType:detectFileKind(url), snapAt:0, archiveUrl:''});
    rememberTags(tags); added++;
  });
  renderSavedSearches(); render();
  document.getElementById('importmsg').textContent='Imported '+added+' bookmark(s)'+
    (skipped?', skipped '+skipped+' (duplicates or invalid).':'.');
}
document.getElementById('exportBtn').addEventListener('click',exportHTML);
document.getElementById('importBtn').addEventListener('click',function(){document.getElementById('importFile').click();});
document.getElementById('importFile').addEventListener('change',function(e){
  var f=e.target.files[0]; if(!f) return;
  var r=new FileReader(); r.onload=function(){ importHTML(r.result); e.target.value=''; };
  r.readAsText(f);
});

render();
document.body.setAttribute('data-harness-ready','true');

