// Safe Markdown-subset renderer for notes.
// Basis: SCN-019 (headings, bold, italic, bullet & numbered lists, block quotes,
//        inline & fenced code, links; raw HTML escaped; only http/https links).

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

function renderInline(s) {
  // protect inline code first so its contents are not further formatted
  const codes = [];
  s = s.replace(/`([^`]+)`/g, (m, c) => { codes.push(c); return '�' + (codes.length - 1) + '�'; });
  s = esc(s);
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
    (m, t, u) => `<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`);
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  s = s.replace(/�(\d+)�/g, (m, i) => `<code>${esc(codes[+i])}</code>`);
  return s;
}

export function renderMarkdown(md) {
  if (!md) return '';
  const lines = String(md).split(/\r?\n/);
  let html = '';
  let listType = null;
  let inQuote = false;
  let inCode = false;
  let codeBuf = [];
  const closeList = () => { if (listType) { html += `</${listType}>`; listType = null; } };
  const closeQuote = () => { if (inQuote) { html += '</blockquote>'; inQuote = false; } };
  for (const ln of lines) {
    if (/^\s*```/.test(ln)) {
      if (inCode) { html += `<pre><code>${esc(codeBuf.join('\n'))}</code></pre>`; codeBuf = []; inCode = false; }
      else { closeList(); closeQuote(); inCode = true; }
      continue;
    }
    if (inCode) { codeBuf.push(ln); continue; }
    const h = ln.match(/^\s*(#{1,3})\s+(.*)$/);
    const ul = ln.match(/^\s*[-*]\s+(.*)$/);
    const ol = ln.match(/^\s*\d+\.\s+(.*)$/);
    const bq = ln.match(/^\s*>\s?(.*)$/);
    if (h) {
      closeList(); closeQuote();
      const lvl = h[1].length + 2;
      html += `<h${lvl}>${renderInline(h[2])}</h${lvl}>`;
    } else if (ul) {
      closeQuote();
      if (listType !== 'ul') { closeList(); html += '<ul>'; listType = 'ul'; }
      html += `<li>${renderInline(ul[1])}</li>`;
    } else if (ol) {
      closeQuote();
      if (listType !== 'ol') { closeList(); html += '<ol>'; listType = 'ol'; }
      html += `<li>${renderInline(ol[1])}</li>`;
    } else if (bq) {
      closeList();
      if (!inQuote) { html += '<blockquote>'; inQuote = true; }
      html += `<div>${renderInline(bq[1])}</div>`;
    } else {
      closeList(); closeQuote();
      if (ln.trim() !== '') html += `<div>${renderInline(ln)}</div>`;
    }
  }
  if (inCode) html += `<pre><code>${esc(codeBuf.join('\n'))}</code></pre>`;
  closeList(); closeQuote();
  return html;
}

