input.content:
:root{
  --bg:#f6f7f9; --card:#ffffff; --ink:#1c2430; --muted:#6b7686;
  --line:#e6e9ef; --accent:#2f6fed; --accent-soft:#eaf1ff; --chip:#eef1f6;
  --warn:#8a5a00; --warn-soft:#fff4e0;
}
*{box-sizing:border-box}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  background:var(--bg);color:var(--ink);line-height:1.5}
body.text-small{font-size:14px}
body.text-medium{font-size:16px}
body.text-large{font-size:18px}
.wrap{max-width:760px;margin:0 auto;padding:32px 20px 80px}
h1{font-size:1.4em;margin:0 0 4px}
.sub{color:var(--muted);font-size:.9em;margin:0 0 24px}

.topbar{display:flex;align-items:center;gap:8px;margin:0 0 20px;flex-wrap:wrap}
.topbtn{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:8px 14px;
  font-size:.87em;color:#41505f;cursor:pointer}
.topbtn:hover{border-color:var(--accent);color:var(--accent)}
.msg{font-size:.82em;color:var(--muted)}

.prefspanel{display:flex;gap:18px;flex-wrap:wrap;background:var(--card);border:1px solid var(--line);
  border-radius:12px;padding:14px 16px;margin:0 0 20px}
.prefspanel[hidden]{display:none}
.prefspanel .pref{display:flex;flex-direction:column;gap:5px}
.prefspanel label{font-size:.75em;font-weight:600;color:var(--muted);text-transform:uppercase}
.prefspanel select{border:1px solid var(--line);border-radius:8px;padding:7px 10px;font-size:.9em;background:#fff;cursor:pointer}

.composer{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:24px;
  box-shadow:0 1px 2px rgba(20,30,50,.04)}
.composer label{display:block;font-size:.72em;font-weight:600;color:var(--muted);margin:0 0 4px;
  letter-spacing:.02em;text-transform:uppercase}
.composer input,.composer textarea{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px 12px;
  font-size:.95em;font-family:inherit;background:#fff;color:var(--ink)}
.composer input:focus,.composer textarea:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.row{margin-bottom:12px}
.two{display:flex;gap:12px;align-items:flex-start}
textarea{resize:vertical;min-height:52px}
.hint{font-size:.78em;color:var(--muted);margin-top:4px}
.save{background:var(--accent);color:#fff;border:none;border-radius:9px;padding:10px 18px;font-size:.95em;font-weight:600;cursor:pointer}
.save:hover{background:#255fd6}
.readlater{display:flex;align-items:center;gap:8px;margin:0 0 14px;font-size:.9em;color:#37414f;cursor:pointer;text-transform:none!important;font-weight:400!important}
.readlater input{width:auto}
.readlater em{color:var(--muted);font-style:normal;font-size:.85em}

.preview{display:flex;align-items:center;gap:10px;background:#f9fbff;border:1px solid var(--accent-soft);
  border-radius:10px;padding:8px 10px;margin-bottom:12px;font-size:.82em;color:var(--muted)}
.preview[hidden]{display:none}
.spinner{width:14px;height:14px;border:2px solid #cdd7ea;border-top-color:var(--accent);border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.fetchnote{background:var(--warn-soft);color:var(--warn);border:1px solid #f0d9a8;border-radius:10px;padding:8px 12px;margin-bottom:12px;font-size:.82em}
.fetchnote[hidden]{display:none}
.fields[hidden]{display:none}
.previmg{width:100%;height:120px;border-radius:10px;margin-bottom:12px;background-size:cover;background-position:center;border:1px solid var(--line)}
.previmg[hidden]{display:none}
.favicon{width:38px;height:38px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;
  color:#fff;font-size:1em;font-weight:700;background:var(--accent);overflow:hidden;position:relative}
.favicon img{width:100%;height:100%;object-fit:cover}
.favicon span{position:absolute}

.tagwrap{position:relative}
.suggest{position:absolute;left:0;right:0;top:100%;background:#fff;border:1px solid var(--line);border-radius:9px;
  box-shadow:0 6px 20px rgba(20,30,50,.12);margin-top:4px;z-index:5;overflow:hidden}
.suggest[hidden]{display:none}
.suggest div{padding:8px 12px;font-size:.9em;cursor:pointer}
.suggest div:hover,.suggest div.active{background:var(--accent-soft)}

.tabs{display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap}
.tab{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:7px 16px;font-size:.9em;color:#41505f;cursor:pointer}
.tab:hover{border-color:var(--accent)}
.tab.active{background:var(--accent);border-color:var(--accent);color:#fff}
.tab .tc{opacity:.7;font-size:.85em;margin-left:4px}

.searchbar{display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);
  border-radius:11px;padding:4px 12px;margin-bottom:14px;box-shadow:0 1px 2px rgba(20,30,50,.04)}
.searchbar:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.searchbar .mag{font-size:.9em;opacity:.6}
.searchbar input{flex:1;border:none;outline:none;font-size:.95em;padding:8px 0;background:transparent;color:var(--ink)}
.clearsearch{border:none;background:none;color:var(--muted);font-size:.9em;cursor:pointer}
.clearsearch[hidden]{display:none}
.savesearch{border:none;background:none;color:var(--accent);font-size:.82em;cursor:pointer;white-space:nowrap;font-weight:600}
.savesearch:disabled{color:var(--muted);cursor:default;font-weight:400;opacity:.6}
mark{background:#fff1a8;color:inherit;border-radius:3px;padding:0 1px}

.savedsearches{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px}
.savedsearches:empty{margin:0}
.savedchip{display:inline-flex;align-items:center;gap:6px;background:#eef4ff;border:1px solid var(--accent-soft);
