    `<span class="savedchip" onclick="runSaved('${s.id}')" title="${esc(s.query)}"><span>★</span>${esc(s.name)}<button class="x" title="Remove" onclick="event.stopPropagation();deleteSaved('${s.id}')">✕</button></span>`).join('');
